import numpy as np
from sklearn.metrics import roc_auc_score


# Define hyperparameters based on iteration number
ITERATION = 10
DATA_DIR = "/mnt/disks/data/birdclef"
METADATA_FILE = os.path.join(DATA_DIR, "train.csv")

# Hyperparameter selection based on iteration % 3
if ITERATION % 3 == 0:
    batch_size = 8
    lr = 0.001
    num_conv_layers = 2
elif ITERATION % 3 == 1:
    batch_size = 16
    lr = 0.0001
    num_conv_layers = 3
else:
    batch_size = 32
    lr = 0.00001
    num_conv_layers = 4

# Additional hyperparameters
dropout_rate = 0.5
weight_decay = 0.001

# Data loader setup
train_loader = get_dataloader(DATA_DIR, METADATA_FILE, batch_size=batch_size)

class BirdClassifier(nn.Module):
    def __init__(self, num_classes=234, num_conv_layers=num_conv_layers, dropout_rate=dropout_rate):
        super(BirdClassifier, self).__init__()
        
        conv_layers = []
        in_channels = 1
        for i in range(num_conv_layers):
            out_channels = 32 * (2 ** i)
            conv_layers.extend([
                nn.Conv2d(in_channels, out_channels, kernel_size=3, padding=1),
                nn.BatchNorm2d(out_channels),
                nn.ReLU(),
                nn.MaxPool2d(kernel_size=2, stride=2)
            ])
            in_channels = out_channels
        
        self.conv_layers = nn.Sequential(*conv_layers)
        self.pool = nn.AdaptiveAvgPool2d((1, 1))
        self.classifier = nn.Sequential(
            nn.Linear(in_channels, 128),
            nn.ReLU(),
            nn.Dropout(dropout_rate),
            nn.Linear(128, num_classes)
        )

    def forward(self, x):
        x = self.conv_layers(x)
        x = self.pool(x).view(x.size(0), -1)
        return torch.sigmoid(self.classifier(x))

# Model initialization
device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
model = BirdClassifier().to(device)

# Loss function and optimizer
criterion = nn.BCELoss()
optimizer = optim.Adam(model.parameters(), lr=lr, weight_decay=weight_decay)

# Training loop
num_epochs = 2
batch_count_limit = 10  # Limit to first ~5000 samples (approx. 10 batches)
model.train()

final_train_loss = None

for epoch in range(num_epochs):
    running_loss = 0.0
    batch_count = 0
    
    for inputs, labels in train_loader:
        if batch_count >= batch_count_limit:
            break
        
        inputs, labels = inputs.to(device), labels.to(device)
        
        optimizer.zero_grad()
        outputs = model(inputs)
        loss = criterion(outputs, labels)
        loss.backward()
        optimizer.step()
        
        running_loss += loss.item()
        print(f"Epoch {epoch+1}, Batch {batch_count+1}, Loss: {loss.item()}")
        
        torch.cuda.empty_cache()  # Prevent GPU fragmentation
        batch_count += 1
    
    final_train_loss = running_loss / batch_count

# Evaluation loop
model.eval()
all_labels = []
all_preds = []

with torch.no_grad():
    for inputs, labels in train_loader:
        inputs, labels = inputs.to(device), labels.to(device)
        outputs = model(inputs)
        
        all_labels.append(labels.cpu().numpy())
        all_preds.append(outputs.cpu().numpy())


all_labels = np.concatenate(all_labels)
all_preds = np.concatenate(all_preds)

final_auc = roc_auc_score(all_labels, all_preds, average='weighted')

# Save metrics
metrics = {
    "final_train_loss": final_train_loss,
    "final_auc": final_auc,
    "num_params": sum(p.numel() for p in model.parameters()),
    "epochs_trained": num_epochs,
    "batch_size": batch_size,
    "training_samples": batch_count_limit * batch_size,
    "eval_samples": len(all_labels)
}

